#!/usr/bin/env python3
"""
overnight_fixer.py — Unattended test-fix agent.

SECURITY ASSUMPTIONS (read before running):
  - Runs in an isolated environment (CI container, dedicated VM, or
    throwaway branch checkout). Model-generated code is executed directly.
  - No production credentials, secrets, or sensitive data in scope.
  - ANTHROPIC_API_KEY set in environment; never logged.
  - Agent commits to the current branch but does NOT push or open PRs.
    A human reviews and merges. That is the intentional gate.

USAGE:
  export ANTHROPIC_API_KEY=sk-...
  python overnight_fixer.py [--max-iterations 20] [--max-cost-usd 10.0]
                             [--test-cmd "pytest tests/ -x --tb=short"]
                             [--timeout-s 3600]
"""

from __future__ import annotations

import argparse
import dataclasses
import json
import logging
import os
import subprocess
import sys
import textwrap
import time
import traceback
from datetime import datetime, timezone
from pathlib import Path
from typing import Any

import anthropic  # pip install anthropic>=0.28

# ---------------------------------------------------------------------------
# Logging — structured, no secrets/PII (Operating Principle 5d)
# ---------------------------------------------------------------------------

LOG_FILE = Path(f"overnight_fixer_{datetime.now(timezone.utc).strftime('%Y%m%dT%H%M%SZ')}.jsonl")

def _make_logger() -> logging.Logger:
    logger = logging.getLogger("overnight_fixer")
    logger.setLevel(logging.DEBUG)
    fmt = logging.Formatter("%(message)s")

    sh = logging.StreamHandler(sys.stdout)
    sh.setLevel(logging.INFO)
    sh.setFormatter(fmt)

    fh = logging.FileHandler(LOG_FILE)
    fh.setLevel(logging.DEBUG)
    fh.setFormatter(fmt)

    logger.addHandler(sh)
    logger.addHandler(fh)
    return logger

log = _make_logger()

def _log(level: str, event: str, **kw: Any) -> None:
    """Emit a structured log line. Never include secret values."""
    record = {"ts": datetime.now(timezone.utc).isoformat(), "event": event, **kw}
    # Scrub any accidental key leakage
    for k in list(record.keys()):
        if any(s in k.lower() for s in ("key", "secret", "token", "password", "auth")):
            record[k] = "***REDACTED***"
    line = json.dumps(record)
    getattr(log, level)(line)


# ---------------------------------------------------------------------------
# Budget — ALL dimensions required by rules/04 §3
# ---------------------------------------------------------------------------

# Pricing as of 2026-06 for claude-sonnet-4 — NEEDS VERIFICATION before use;
# re-check https://www.anthropic.com/pricing before pinning.
# Falsification: if actual spend diverges from estimate by >20%, the price
# constants are wrong — update them.
_INPUT_PRICE_PER_MTOK  = 3.00   # USD per million input tokens  [needs-verification]
_OUTPUT_PRICE_PER_MTOK = 15.00  # USD per million output tokens [needs-verification]

@dataclasses.dataclass
class Budget:
    max_iterations: int        = 20
    max_cost_usd: float        = 10.0
    wall_clock_timeout_s: int  = 3600   # 1 hour default
    max_consecutive_errors: int = 3     # same tool failing → abort
    max_repeat_calls: int      = 3      # identical (tool, args) → loop detection

    # Accumulators
    iterations: int            = 0
    total_input_tokens: int    = 0
    total_output_tokens: int   = 0
    consecutive_errors: int    = 0
    _start_time: float         = dataclasses.field(default_factory=time.monotonic)
    _last_call_key: str        = ""
    _repeat_count: int         = 0

    @property
    def elapsed_s(self) -> float:
        return time.monotonic() - self._start_time

    @property
    def estimated_cost_usd(self) -> float:
        return (
            self.total_input_tokens  / 1_000_000 * _INPUT_PRICE_PER_MTOK +
            self.total_output_tokens / 1_000_000 * _OUTPUT_PRICE_PER_MTOK
        )

    def record_api_call(self, input_tok: int, output_tok: int) -> None:
        self.total_input_tokens  += input_tok
        self.total_output_tokens += output_tok

    def check_repeat(self, call_key: str) -> bool:
        """Return True (abort) if the same call has been made too many times."""
        if call_key == self._last_call_key:
            self._repeat_count += 1
        else:
            self._last_call_key = call_key
            self._repeat_count  = 1
        return self._repeat_count > self.max_repeat_calls

    def exhausted(self) -> tuple[bool, str]:
        """Return (True, reason) if any budget dimension is exceeded."""
        if self.iterations >= self.max_iterations:
            return True, f"max_iterations={self.max_iterations} reached"
        if self.estimated_cost_usd >= self.max_cost_usd:
            return True, f"max_cost_usd={self.max_cost_usd:.2f} reached (est. ${self.estimated_cost_usd:.2f})"
        if self.elapsed_s >= self.wall_clock_timeout_s:
            return True, f"wall_clock_timeout={self.wall_clock_timeout_s}s reached"
        if self.consecutive_errors >= self.max_consecutive_errors:
            return True, f"max_consecutive_errors={self.max_consecutive_errors} reached"
        return False, ""


