# ---------------------------------------------------------------------------
# Tool implementations
# ---------------------------------------------------------------------------

class ToolExecutor:
    def __init__(self, project_root: Path, test_cmd: str, budget: Budget) -> None:
        self.root     = project_root.resolve()
        self.test_cmd = test_cmd
        self.budget   = budget

    def _safe_path(self, rel: str) -> Path | None:
        """Resolve path and verify it stays inside project root."""
        try:
            p = (self.root / rel).resolve()
            p.relative_to(self.root)   # raises ValueError if outside
            return p
        except (ValueError, Exception):
            return None

    # --- run_tests -----------------------------------------------------------

    def run_tests(self) -> dict:
        _log("info", "tool.run_tests.start", cmd=self.test_cmd)
        try:
            result = subprocess.run(
                self.test_cmd,
                shell=True,          # noqa: S602 — intentional; cmd is operator-supplied
                capture_output=True,
                text=True,
                cwd=self.root,
                timeout=300,         # 5-minute per-run hard cap
            )
            combined = (result.stdout + "\n" + result.stderr).strip()
            # Bound output size — rules/04 §2
            truncated = combined[:8000]
            if len(combined) > 8000:
                truncated += f"\n... [truncated {len(combined)-8000} chars]"
            passed = result.returncode == 0
            _log("info", "tool.run_tests.done",
                 exit_code=result.returncode, passed=passed,
                 output_len=len(combined))
            self.budget.consecutive_errors = 0  # successful tool call
            return {"passed": passed, "exit_code": result.returncode, "output": truncated}
        except subprocess.TimeoutExpired:
            self.budget.consecutive_errors += 1
            _log("warning", "tool.run_tests.timeout")
            return {"passed": False, "exit_code": -1,
                    "output": "ERROR: test run timed out after 300s"}
        except Exception as exc:
            self.budget.consecutive_errors += 1
            _log("error", "tool.run_tests.exception", exc=str(exc))
            return {"passed": False, "exit_code": -1,
                    "output": f"ERROR: could not run tests: {exc}"}

    # --- read_file -----------------------------------------------------------

    def read_file(self, path: str) -> str:
        p = self._safe_path(path)
        if p is None:
            return f"ERROR: path '{path}' is outside the project root or invalid"
        if not p.exists():
            return f"ERROR: file '{path}' does not exist — do not retry with the same path"
        try:
            content = p.read_text(encoding="utf-8")
            # Bound output — rules/04 §2
            if len(content) > 20_000:
                content = content[:20_000] + f"\n... [truncated; file is {len(content)} chars]"
            _log("debug", "tool.read_file", path=path, chars=len(content))
            self.budget.consecutive_errors = 0
            return content
        except Exception as exc:
            self.budget.consecutive_errors += 1
            return f"ERROR: could not read '{path}': {exc}"

    # --- write_file ----------------------------------------------------------

    def write_file(self, path: str, content: str) -> str:
        p = self._safe_path(path)
        if p is None:
            return f"ERROR: path '{path}' is outside the project root or invalid"
        if not p.exists():
            return f"ERROR: file '{path}' does not exist — will not create new files; only fix existing ones"
        try:
            # Atomic write via temp file
            tmp = p.with_suffix(p.suffix + ".tmp")
            tmp.write_text(content, encoding="utf-8")
            tmp.replace(p)
            _log("info", "tool.write_file", path=path, chars=len(content))
            self.budget.consecutive_errors = 0
            return "OK"
        except Exception as exc:
            self.budget.consecutive_errors += 1
            return f"ERROR: could not write '{path}': {exc}"

    # --- list_files ----------------------------------------------------------

    def list_files(self, include_tests: bool = False) -> str:
        try:
            files = sorted(self.root.rglob("*.py"))
            rel   = [str(f.relative_to(self.root)) for f in files]
            if not include_tests:
                rel = [r for r in rel
                       if not (Path(r).name.startswith("test_")
                               or Path(r).name.endswith("_test.py"))]
            # Cap list size
            if len(rel) > 200:
                rel = rel[:200] + [f"... and {len(rel)-200} more"]
            _log("debug", "tool.list_files", count=len(rel))
            self.budget.consecutive_errors = 0
            return json.dumps(rel)
        except Exception as exc:
            self.budget.consecutive_errors += 1
            return f"ERROR: {exc}"

    # --- commit_fix ----------------------------------------------------------

    def commit_fix(self, message: str) -> str:
        # Sanitize message — no shell injection via model-supplied string
        safe_msg = message.replace('"', "'").replace("\n", " ")[:200]
        try:
            # Stage all modified tracked files (not untracked — don't add new files)
            subprocess.run(
                ["git", "add", "-u"],
                cwd=self.root, check=True, capture_output=True
            )
            result = subprocess.run(
                ["git", "commit", "-m", safe_msg],
                cwd=self.root, capture_output=True, text=True
            )
            if result.returncode != 0:
                if "nothing to commit" in result.stdout + result.stderr:
                    return "OK: nothing to commit (no changes staged)"
                return f"ERROR: git commit failed: {result.stderr.strip()}"
            sha = subprocess.run(
                ["git", "rev-parse", "--short", "HEAD"],
                cwd=self.root, capture_output=True, text=True
            ).stdout.strip()
            _log("info", "tool.commit_fix", sha=sha, message=safe_msg)
            self.budget.consecutive_errors = 0
            return f"OK: {sha}"
        except Exception as exc:
            self.budget.consecutive_errors += 1
            return f"ERROR: {exc}"

    # --- report_blocked ------------------------------------------------------

    def report_blocked(self, reason: str, failing_tests: list[str]) -> str:
        # This is a signal to the harness, not a real tool action.
        # The harness catches it via the return value.
        _log("warning", "tool.report_blocked",
             reason=reason, failing_tests=failing_tests)
        return "BLOCKED"

    # --- dispatch ------------------------------------------------------------

    def dispatch(self, name: str, args: dict) -> str:
        if name == "run_tests":
            return json.dumps(self.run_tests())
        elif name == "read_file":
            return self.read_file(args.get("path", ""))
        elif name == "write_file":
            return self.write_file(args.get("path", ""), args.get("content", ""))
        elif name == "list_files":
            return self.list_files(args.get("include_tests", False))
        elif name == "commit_fix":
            return self.commit_fix(args.get("message", "auto-fix"))
        elif name == "report_blocked":
            return self.report_blocked(
                args.get("reason", ""),
                args.get("failing_tests", []),
            )
        else:
            return f"ERROR: unknown tool '{name}'"


# ---------------------------------------------------------------------------
# Agent loop
# ---------------------------------------------------------------------------

SYSTEM_PROMPT = textwrap.dedent("""
    You are an automated test-fix agent running overnight with no human present.
    Your job: keep the Python test suite green.

    WORKFLOW:
    1. Call run_tests to see the current state.
    2. If all tests pass, call commit_fix (if there are uncommitted changes) and stop.
    3. If tests fail, read the relevant source files, understand the root cause,
       write a minimal targeted fix, then call run_tests again to verify.
    4. Repeat until tests pass or you are blocked.

    RULES:
    - Fix source code, not tests (unless the test itself is clearly wrong and
      you can justify it in the commit message).
    - Make the smallest change that fixes the failure. Do not refactor.
    - Never call commit_fix while tests are failing.
    - If you cannot determine a safe fix, call report_blocked with a clear
      explanation — do not guess or make speculative changes.
    - You have a limited budget of iterations and cost. Be efficient.
      Prioritize understanding the failure before writing any code.
    - If you find yourself repeating the same action, stop and call report_blocked.
""").strip()


def run_agent(
    *,
    project_root: Path,
    test_cmd: str,
    budget: Budget,
    model: str = "claude-sonnet-4-5",
) -> dict:
    """
    Run the agent loop. Returns a summary dict.
    Never raises — all exceptions are caught and returned in the summary.
    """
    client   = anthropic.Anthropic()   # reads ANTHROPIC_API_KEY from env
    executor = ToolExecutor(project_root, test_cmd, budget)
    messages: list[dict] = []

    outcome = "unknown"
    outcome_detail = ""

    _log("info", "agent.start",
         model=model, project_root=str(project_root),
         test_cmd=test_cmd,
         budget_iterations=budget.max_iterations,
         budget_cost_usd=budget.max_cost_usd,
         budget_wall_s=budget.wall_clock_timeout_s)

    try:
        # Seed the conversation — tell the model to begin
        messages.append({
            "role": "user",
            "content": (
                "The overnight test-fix session is starting. "
                "Begin by running the test suite to assess the current state."
            ),
        })

        while True:
            # ── Budget check (rules/04 §3) ──────────────────────────────────
            exhausted, reason = budget.exhausted()
            if exhausted:
                outcome        = "budget_exhausted"
                outcome_detail = reason
                _log("warning", "agent.budget_exhausted", reason=reason,
                     iterations=budget.iterations,
                     est_cost_usd=f"{budget.estimated_cost_usd:.4f}")
