@dataclass
class Budget:
    max_iterations: int = 20
    max_total_tokens: int = 400_000
    max_cost_usd: float = 5.00
    wall_clock_timeout_s: int = 8 * 3600   # 8 hours
    max_consecutive_errors: int = 3
    max_repeat_calls: int = 3              # same (tool, args) hash → loop

    # Runtime state — not config
    iterations_used: int = 0
    tokens_used: int = 0
    cost_usd_used: float = 0.0
    start_time: float = field(default_factory=time.monotonic)
    consecutive_errors: int = 0
    _call_counts: dict[str, int] = field(default_factory=dict)

    # Approximate pricing (needs-verification: re-check before use;
    # these are claude-3-5-sonnet-20241022 list prices as of mid-2025)
    _INPUT_PRICE_PER_M: float = 3.00
    _OUTPUT_PRICE_PER_M: float = 15.00

    def record_usage(self, input_tokens: int, output_tokens: int) -> None:
        self.tokens_used += input_tokens + output_tokens
        self.cost_usd_used += (
            input_tokens / 1_000_000 * self._INPUT_PRICE_PER_M
            + output_tokens / 1_000_000 * self._OUTPUT_PRICE_PER_M
        )

    def record_call(self, tool: str, args_hash: str) -> None:
        key = f"{tool}:{args_hash}"
        self.call_counts[key] = self.call_counts.get(key, 0) + 1

    @property
    def call_counts(self) -> dict[str, int]:
        return self._call_counts

    def check_repeat(self, tool: str, args_hash: str) -> bool:
        """Return True if this (tool, args) has been called too many times."""
        key = f"{tool}:{args_hash}"
        return self.call_counts.get(key, 0) >= self.max_repeat_calls

    def elapsed_s(self) -> float:
        return time.monotonic() - self.start_time

    def exhausted(self) -> tuple[bool, str]:
        """Return (is_exhausted, reason). Checks all dimensions."""
        if self.iterations_used >= self.max_iterations:
            return True, f"max_iterations={self.max_iterations} reached"
        if self.tokens_used >= self.max_total_tokens:
            return True, f"max_total_tokens={self.max_total_tokens} reached"
        if self.cost_usd_used >= self.max_cost_usd:
            return True, f"max_cost_usd=${self.max_cost_usd:.2f} reached (used ${self.cost_usd_used:.2f})"
        if self.elapsed_s() >= self.wall_clock_timeout_s:
            return True, f"wall_clock_timeout={self.wall_clock_timeout_s}s reached"
        if self.consecutive_errors >= self.max_consecutive_errors:
            return True, f"max_consecutive_errors={self.max_consecutive_errors} reached"
        return False, ""

    def summary(self) -> dict[str, Any]:
        return {
            "iterations": self.iterations_used,
            "tokens": self.tokens_used,
            "cost_usd": round(self.cost_usd_used, 4),
            "elapsed_s": round(self.elapsed_s(), 1),
        }


