class ToolExecutor:
    def __init__(
        self,
        repo_root: Path,
        test_cmd: list[str],
        test_timeout_s: int,
        logger: logging.Logger,
        budget: Budget,
    ) -> None:
        self.repo_root = repo_root.resolve()
        self.test_cmd = test_cmd
        self.test_timeout_s = test_timeout_s
        self.logger = logger
        self.budget = budget
        self._written_keys: set[str] = set()  # idempotency for write_file

    def _safe_path(self, rel: str) -> tuple[Path | None, str]:
        """
        Resolve a relative path and verify it stays inside repo_root.
        Returns (resolved_path, "") on success or (None, error_message) on failure.
        """
        try:
            resolved = (self.repo_root / rel).resolve()
        except Exception as exc:
            return None, f"path resolution error: {exc}"
        try:
            resolved.relative_to(self.repo_root)
        except ValueError:
            return None, (
                f"path '{rel}' resolves outside repository root — "
                "only paths inside the repository are allowed; do not retry with this path"
            )
        return resolved, ""

    def run_tests(self, extra_args: list[str] | None = None) -> dict[str, Any]:
        cmd = self.test_cmd + (extra_args or [])
        _log(self.logger, "info", "run_tests", cmd=cmd)
        try:
            result = subprocess.run(
                cmd,
                cwd=self.repo_root,
                capture_output=True,
                text=True,
                timeout=self.test_timeout_s,
            )
        except subprocess.TimeoutExpired:
            return {
                "exit_code": -1,
                "error": f"test run timed out after {self.test_timeout_s}s",
                "stdout": "",
                "stderr": "",
                "retryable": False,
            }
        except Exception as exc:
            return {
                "exit_code": -1,
                "error": f"failed to launch test process: {exc}",
                "stdout": "",
                "stderr": "",
                "retryable": False,
            }

        # Cap output size to avoid flooding context (rules/04 §2)
        MAX_OUTPUT = 20_000
        stdout = result.stdout[-MAX_OUTPUT:] if len(result.stdout) > MAX_OUTPUT else result.stdout
        stderr = result.stderr[-MAX_OUTPUT:] if len(result.stderr) > MAX_OUTPUT else result.stderr
        truncated = len(result.stdout) > MAX_OUTPUT or len(result.stderr) > MAX_OUTPUT

        _log(
            self.logger, "info", "run_tests_result",
            exit_code=result.returncode,
            truncated=truncated,
        )
        return {
            "exit_code": result.returncode,
            "stdout": stdout,
            "stderr": stderr,
            "truncated": truncated,
            "note": (
                "exit_code 0 means all tests pass. "
                + ("Output was truncated to last 20 000 chars. " if truncated else "")
            ),
        }

    def read_file(self, path: str) -> dict[str, Any]:
        resolved, err = self._safe_path(path)
        if err:
            return {"error": err, "retryable": False}
        if not resolved.exists():
            return {
                "error": f"file '{path}' does not exist — do not retry with this path",
                "retryable": False,
            }
        if not resolved.is_file():
            return {
                "error": f"'{path}' is not a file — do not retry with this path",
                "retryable": False,
            }
        MAX_READ = 500_000
        try:
            contents = resolved.read_text(encoding="utf-8", errors="replace")
        except Exception as exc:
            return {"error": f"read error: {exc}", "retryable": False}
        truncated = len(contents) > MAX_READ
        return {
            "path": path,
            "contents": contents[:MAX_READ],
            "truncated": truncated,
            "note": "Truncated to 500 000 chars." if truncated else "",
        }

    def write_file(
        self, path: str, contents: str, idempotency_key: str
    ) -> dict[str, Any]:
        # Idempotency: skip duplicate writes (rules/04 §2)
        if idempotency_key in self._written_keys:
            _log(self.logger, "info", "write_file_skipped_duplicate", path=path, key=idempotency_key)
            return {"status": "ok", "note": "duplicate write skipped (idempotency)"}

        resolved, err = self._safe_path(path)
        if err:
            return {"error": err, "retryable": False}

        MAX_WRITE = 500_000
        if len(contents.encode("utf-8")) > MAX_WRITE:
            return {
                "error": "contents exceed 500 KB limit — split into smaller files",
                "retryable": False,
            }

        _log(self.logger, "info", "write_file", path=path, bytes=len(contents.encode()))
        try:
            resolved.parent.mkdir(parents=True, exist_ok=True)
            resolved.write_text(contents, encoding="utf-8")
        except Exception as exc:
            return {"error": f"write error: {exc}", "retryable": False}

        self._written_keys.add(idempotency_key)
        return {"status": "ok", "path": path}

    def list_files(self, directory: str, pattern: str = "**/*.py") -> dict[str, Any]:
        resolved, err = self._safe_path(directory)
        if err:
            return {"error": err, "retryable": False}
        if not resolved.is_dir():
            return {
                "error": f"'{directory}' is not a directory — do not retry with this path",
                "retryable": False,
            }
        try:
            files = sorted(
                str(p.relative_to(self.repo_root))
                for p in resolved.glob(pattern)
                if p.is_file()
            )
        except Exception as exc:
            return {"error": f"glob error: {exc}", "retryable": False}
        return {
            "files": files[:200],  # cap list size
            "truncated": len(files) > 200,
            "note": "Empty list means no matching files — do not retry with the same path." if not files else "",
        }

    def dispatch(self, tool_name: str, tool_input: dict[str, Any]) -> dict[str, Any]:
        if tool_name == "run_tests":
            return self.run_tests(tool_input.get("extra_args"))
        if tool_name == "read_file":
            return self.read_file(tool_input["path"])
        if tool_name == "write_file":
            return self.write_file(
                tool_input["path"],
                tool_input["contents"],
                tool_input["idempotency_key"],
            )
        if tool_name == "list_files":
            return self.list_files(
                tool_input["directory"],
                tool_input.get("pattern", "**/*.py"),
            )
        return {"error": f"unknown tool '{tool_name}'", "retryable": False}


