            return f"max_iterations={self.max_iterations} reached"
        if self.estimated_cost_usd >= self.max_cost_usd:
            return f"max_cost_usd=${self.max_cost_usd:.2f} reached (est. ${self.estimated_cost_usd:.2f})"
        if self.elapsed_s >= self.wall_clock_timeout_s:
            return f"wall_clock_timeout={self.wall_clock_timeout_s}s reached"
        if self.consecutive_errors >= self.max_consecutive_errors:
            return f"max_consecutive_errors={self.max_consecutive_errors} reached"
        return None


# ---------------------------------------------------------------------------
# Boundary enforcement (rules/04 §3a — boundary stated alongside done-criterion)
#
# Done-criterion : pytest exits 0 AND change-list written.
# Boundary       : no test file deleted or weakened; no file outside
#                  allowed_roots written; no test assertion removed.
# ---------------------------------------------------------------------------
def _is_allowed_write(path: Path, src_root: Path, test_root: Path) -> tuple[bool, str]:
    """
    Returns (allowed, reason).
    Allowed writes: files under src_root, OR new test files under test_root.
    Forbidden: modifying existing test files (weakening guard).
    """
    try:
        path = path.resolve()
    except Exception:
        return False, "could not resolve path"

    under_src = _is_subpath(path, src_root.resolve())
    under_test = _is_subpath(path, test_root.resolve())

    if not (under_src or under_test):
        return False, f"path {path} is outside src_root={src_root} and test_root={test_root}"

    if under_test and path.exists():
        return False, (
            f"refusing to modify existing test file {path} "
            "(boundary: test files are read-only; agent may only add new test files)"
        )

    return True, "ok"


def _is_subpath(child: Path, parent: Path) -> bool:
    try:
        child.relative_to(parent)
        return True
    except ValueError:
        return False


def _check_no_assertion_removal(original: str, proposed: str, filepath: Path) -> tuple[bool, str]:
    """
    Heuristic guard: if the file is a test file, ensure no `assert` statements
    were removed. Not a complete AST diff — flags for human review if triggered.
    """
    if "test" not in filepath.name.lower():
        return True, "ok"
    orig_asserts = original.count("\n    assert ") + original.count("\nassert ")
    new_asserts = proposed.count("\n    assert ") + proposed.count("\nassert ")
    if new_asserts < orig_asserts:
        return False, (
            f"proposed change to {filepath} reduces assert count "
            f"({orig_asserts} → {new_asserts}); refusing (boundary violation)"
        )
    return True, "ok"


# ---------------------------------------------------------------------------
# Tool implementations
# ---------------------------------------------------------------------------
MAX_OUTPUT_BYTES = 24_000  # ~6k tokens; truncate tool output to protect context


def _truncate(text: str, label: str = "output") -> str:
    encoded = text.encode()
    if len(encoded) <= MAX_OUTPUT_BYTES:
        return text
    kept = encoded[:MAX_OUTPUT_BYTES].decode(errors="replace")
    return kept + f"\n\n[{label} truncated at {MAX_OUTPUT_BYTES} bytes; {len(encoded)} total]"


def tool_run_tests(test_cmd: str, repo_root: Path) -> dict[str, Any]:
    """Run the test suite. Returns structured result the model can act on."""
    log.info("tool:run_tests cmd=%r", test_cmd)
    try:
        result = subprocess.run(
            test_cmd,
            shell=True,
            capture_output=True,
            text=True,
            cwd=str(repo_root),
            timeout=300,
        )
        combined = result.stdout + ("\n--- stderr ---\n" + result.stderr if result.stderr.strip() else "")
        return {
            "exit_code": result.returncode,
            "passed": result.returncode == 0,
            "output": _truncate(combined, "test output"),
        }
    except subprocess.TimeoutExpired:
        return {
            "exit_code": -1,
            "passed": False,
            "output": "Test run timed out after 300 s. Do not retry with the same command.",
            "retryable": False,
        }
    except Exception as exc:
        return {
            "exit_code": -1,
            "passed": False,
            "output": f"Failed to launch test runner: {exc}. Check test_cmd argument.",
            "retryable": False,
        }


def tool_read_file(path_str: str, repo_root: Path) -> dict[str, Any]:
    """Read a source file. Returns content or a structured error."""
    log.info("tool:read_file path=%r", path_str)
    path = (repo_root / path_str).resolve()
    if not _is_subpath(path, repo_root.resolve()):
        return {"error": f"path {path_str!r} is outside the repository root — do not retry with a path outside the repo"}
    if not path.exists():
        return {"error": f"file not found: {path_str} — check the path and try again"}
    try:
        content = path.read_text(encoding="utf-8")
        return {"content": _truncate(content, f"file {path_str}"), "path": path_str}
    except Exception as exc:
        return {"error": f"could not read {path_str}: {exc} — do not retry"}


def tool_write_file(
    path_str: str,
    content: str,
    repo_root: Path,
    src_root: Path,
    test_root: Path,
) -> dict[str, Any]:
    """
    Write (create or overwrite) a source file.
    Enforces boundary: no existing test files, no paths outside allowed roots.
    """
    log.info("tool:write_file path=%r bytes=%d", path_str, len(content.encode()))
    path = (repo_root / path_str).resolve()

    allowed, reason = _is_allowed_write(path, src_root, test_root)
    if not allowed:
        return {
            "error": reason,
            "retryable": False,
            "hint": "You may only write files under the source root. Test files are read-only.",
        }

    # Syntax check for .py files before writing
    if path.suffix == ".py":
        try:
            ast.parse(content)
        except SyntaxError as exc:
            return {
                "error": f"proposed content has a Python syntax error: {exc} — fix the syntax and retry",
                "retryable": True,
            }

    # Assertion-removal guard for test files
    if path.exists():
        original = path.read_text(encoding="utf-8")
        ok, reason2 = _check_no_assertion_removal(original, content, path)
        if not ok:
            return {"error": reason2, "retryable": False}

    try:
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(content, encoding="utf-8")
        return {"written": path_str, "bytes": len(content.encode())}
    except Exception as exc:
        return {"error": f"write failed: {exc}", "retryable": False}


def tool_list_files(pattern: str, repo_root: Path) -> dict[str, Any]:
    """Glob for source files. Pattern is relative to repo root, e.g. 'src/**/*.py'."""
    log.info("tool:list_files pattern=%r", pattern)
    try:
        matches = sorted(str(p.relative_to(repo_root)) for p in repo_root.glob(pattern))
        if not matches:
            return {"files": [], "note": "no files matched — try a broader pattern"}
        return {"files": matches[:200]}  # cap at 200 entries
    except Exception as exc:
        return {"error": f"glob failed: {exc}"}


# ---------------------------------------------------------------------------
# Tool schema (rules/04 §2 — when-to-call, strict schema, bounded output,
#              actionable errors, explicit empty-result semantics)
# ---------------------------------------------------------------------------
TOOLS = [
    {
        "name": "run_tests",
        "description": (
