            "properties": {},
            "required": [],
            "additionalProperties": False,
        },
    },
    {
        "name": "read_file",
        "description": (
            "Read the full content of a source file. "
            "Call this when you need to understand the code before writing a fix. "
            "Path is relative to the repository root (e.g. 'src/mymodule/utils.py'). "
