                }
            },
            "required": ["pattern"],
            "additionalProperties": False,
        },
    },
]


# ---------------------------------------------------------------------------
# Tool dispatch — harness owns execution (rules/04 §2)
# ---------------------------------------------------------------------------
def dispatch_tool(
    name: str,
    args: dict[str, Any],
    *,
    test_cmd: str,
    repo_root: Path,
    src_root: Path,
    test_root: Path,
) -> dict[str, Any]:
    if name == "run_tests":
        return tool_run_tests(test_cmd, repo_root)
    if name == "read_file":
        return tool_read_file(args.get("path", ""), repo_root)
    if name == "write_file":
        return tool_write_file(
            args.get("path", ""),
            args.get("content", ""),
            repo_root,
            src_root,
            test_root,
        )
    if name == "list_files":
        return tool_list_files(args.get("pattern", "**/*.py"), repo_root)
    return {"error": f"unknown tool {name!r} — do not retry"}


# ---------------------------------------------------------------------------
# Change-list accumulator (part of done-criterion: "change-list written")
# ---------------------------------------------------------------------------
@dataclass
class ChangeList:
    entries: list[dict[str, Any]] = field(default_factory=list)

    def record(self, path: str, iteration: int) -> None:
        self.entries.append({"path": path, "iteration": iteration, "ts": datetime.now(timezone.utc).isoformat()})

    def write(self, dest: Path) -> None:
        dest.write_text(json.dumps(self.entries, indent=2), encoding="utf-8")
        log.info("change-list written to %s (%d entries)", dest, len(self.entries))


# ---------------------------------------------------------------------------
# System prompt
# ---------------------------------------------------------------------------
def build_system_prompt(test_cmd: str, src_root: Path, budget: Budget) -> str:
    return textwrap.dedent(f"""
        You are an automated test-repair agent running overnight on a Python repository.

        ## Your goal
        Make the test suite pass: `{test_cmd}` must exit with code 0.

        ## Boundary (hard constraints — the harness enforces these, not just you)
        - You may only write files under the source root ({src_root}).
        - You may add new test files but NEVER modify existing test files.
        - You may not delete files.
        - You may not weaken or remove assertions.

        ## Budget
        You have at most {budget.max_iterations} tool-call rounds and an estimated
        cost cap of ${budget.max_cost_usd:.2f}. Prioritize the highest-impact fixes first.
        When you are close to the limit, write a summary of remaining failures and stop.

        ## Workflow
        1. Call run_tests to see the current state.
        2. Read the relevant source files.
        3. Write a fix.
        4. Call run_tests again to verify.
        5. Repeat until all tests pass or budget is exhausted.

        ## Rules
        - Do not call run_tests twice in a row with no file change between calls.
        - Do not retry a tool call with identical arguments after a non-retryable error.
        - When tests pass (exit_code=0), stop immediately and say "DONE".
        - If you are stuck after 3 attempts on the same failure, describe the blockage
          and move on to the next failure.
    """).strip()


# ---------------------------------------------------------------------------
# Main agent loop (rules/04 §3 — all budget dimensions, stop_reason handling,
#                  rules/04 §3a — done-criterion + boundary + judge separate)
# ---------------------------------------------------------------------------
def run_agent(
    *,
    test_cmd: str,
    repo_root: Path,
    src_root: Path,
    test_root: Path,
    model: str,
    budget: Budget,
    change_list_path: Path,
) -> int:
    """
    Returns exit code: 0 = suite green, 1 = budget exhausted / error.

    Done-criterion : run_tests returns exit_code=0 AND change-list written.
    Boundary       : enforced in tool dispatch (write_file), not just prompt.
    Judge          : a separate subprocess re-runs pytest after the loop exits
                     (see __main__ block) — the agent cannot influence that call.
    """
    client = anthropic.Anthropic()  # reads ANTHROPIC_API_KEY from env
    changes = ChangeList()
    messages: list[dict[str, Any]] = []
    system = build_system_prompt(test_cmd, src_root, budget)

    # Seed the conversation: ask the agent to start by running the tests.
    # This is the first user turn; the agent must call run_tests before
    # it can produce any answer — structurally enforced because we only
    # finalize when run_tests has returned exit_code=0 this run (§2 mandatory tool).
    messages.append({
        "role": "user",
        "content": (
            "The overnight repair session has started. "
            "Begin by running the test suite to see the current state, "
            "then fix any failures you find."
        ),
    })

    suite_passed_this_run = False  # harness tracks this, not the model's prose

    while True:
        # --- Budget check (all six dimensions) ---
        reason = budget.check()
        if reason:
            log.warning("BUDGET EXHAUSTED: %s", reason)
            _persist_partial_state(messages, changes, change_list_path, reason)
            return 1

        budget.iterations += 1
        log.info(
            "iteration=%d cost_est=$%.3f elapsed=%.0fs",
            budget.iterations,
            budget.estimated_cost_usd,
            budget.elapsed_s,
        )

        # --- Model call ---
        try:
            response = client.messages.create(
                model=model,
                max_tokens=4096,
                system=system,
                tools=TOOLS,
                messages=messages,
            )
        except anthropic.APIError as exc:
            log.error("API error: %s", exc)
            budget.

