        return int(header)
    try:
        dt = datetime.strptime(header, "%a, %d %b %Y %H:%M:%S %Z")
        dt = dt.replace(tzinfo=timezone.utc)
        _now = now if now is not None else datetime.now(timezone.utc)
        return max(int((dt - _now).total_seconds()), 0)
    except ValueError:
